UPDATE orders
SET status = 'CANCELLED',
    updated_at = #{updatedAt}
WHERE id = #{orderId}
  AND status = 'PENDING_PAYMENT'

UPDATE orders
SET status = 'PAID',
    paid_at = #{paidAt},
    updated_at = #{updatedAt}
WHERE id = #{orderId}
  AND status = 'PENDING_PAYMENT'
  AND expires_at > #{paidAt}

mapper.select:
SELECT

FROM orders
WHERE status = 'PENDING_PAYMENT'
  AND expires_at <= #{now}
ORDER BY expires_at ASC
LIMIT #{limit}

mapper.update:
UPDATE orders
SET status = 'EXPIRED',
    updated_at = #{updatedAt}
WHERE id = #{orderId}
  AND status = 'PENDING_PAYMENT'
  AND expires_at <= #{updatedAt}
